/** The project-registry tokens (docs/DEPOT.md-adjacent): the shared
 * resolver expands {{registry:<slug>}} to the generated registry's
 * version — prose stays hand-written, numbers live in exactly one
 * place (src/content/projects/_registry.json, regenerated by
 * scripts/refresh-projects.mjs). */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";
import {
  expandSection,
  expandRegistryTokens,
  makeResolver,
  setProjectRegistry,
} from "../src/renderer/index.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

test("tokens expand to the registry version; unknown slugs stay visible", () => {
  setProjectRegistry({
    herbctl: { version: "v1.18.0" },
    herbstutil: { version: "v1.1.0" },
  });
  assert.equal(expandRegistryTokens("{{registry:herbctl}}"), "v1.18.0");
  assert.equal(
    expandRegistryTokens(
      "herbstutil {{registry:herbstutil}} + {{registry:nope}}",
    ),
    "herbstutil v1.1.0 + {{registry:nope}}",
  );
  // re-set to empty: back to visible tokens (never silently blank)
  setProjectRegistry(undefined);
  assert.equal(
    expandRegistryTokens("{{registry:herbctl}}"),
    "{{registry:herbctl}}",
  );
});

test("expandSection expands content strings AND the status line", () => {
  setProjectRegistry({ herbctl: { version: "v1.18.0" } });
  const resolveTarget = makeResolver({});
  const section = expandSection(
    {
      heading: "links",
      status: "{{registry:herbctl}}",
      content: [
        "{{registry:herbctl}}",
        { heading: "x", content: "{{registry:herbctl}}" },
      ],
    },
    resolveTarget,
  );
  assert.equal(section.status, "v1.18.0");
  assert.equal(section.content[0], "v1.18.0");
  assert.equal(section.content[1].content, "v1.18.0");
  // sections without content keep their exact shape (no content key added)
  const bare = expandSection({ heading: "x" }, resolveTarget);
  assert.equal("content" in bare, false);
});

test("every token in the authored project JSON resolves in the generated registry", () => {
  const registry = JSON.parse(
    fs.readFileSync(
      path.join(root, "src/content/projects/_registry.json"),
      "utf8",
    ),
  );
  const dir = path.join(root, "src/content/projects");
  const tokens = [];
  for (const file of fs.readdirSync(dir)) {
    if (!file.endsWith(".json")) continue;
    const text = fs.readFileSync(path.join(dir, file), "utf8");
    tokens.push(
      ...[...text.matchAll(/\{\{registry:([a-z0-9-]+)\}\}/g)].map(
        (m) => `${file}: ${m[1]}`,
      ),
    );
  }
  assert.ok(tokens.length > 0, "the fleet actually carries tokens");
  for (const token of tokens) {
    const slug = token.split(": ")[1];
    assert.ok(
      registry.projects[slug]?.version,
      `token with no registry version: ${token}`,
    );
  }
});

test("the registry is fresh enough to publish: generatedAt is recent", () => {
  const registry = JSON.parse(
    fs.readFileSync(
      path.join(root, "src/content/projects/_registry.json"),
      "utf8",
    ),
  );
  const ageDays = (Date.now() - Date.parse(registry.generatedAt)) / 86_400_000;
  assert.ok(
    ageDays < 60,
    `the registry is ${Math.round(ageDays)} days stale — run scripts/refresh-projects.mjs`,
  );
});
